  "task": "Differentiate among differential diagnoses for a right upper lobe lesion in a patient with prior TB and haemoptysis, based on chest X-ray morphology",
  "anatomy": "Right upper lobe lung parenchyma",
  "option_differences": [
    {
      "attribute": "cavity morphology and internal features",
      "question": "Does the lesion show a well-defined cavity with an air crescent sign (suggesting aspergilloma) or a thick-walled cavity without internal structure (suggesting TB or abscess)?",
      "option_labels": ["B", "D"],
      "image_ids": ["image:1"]
    },
    {
      "attribute": "presence of adjacent fibrosis/pleural tethering vs. mass-like opacity",
      "question": "Is the lesion associated with volume loss, pleural thickening, and fibrotic bands (favoring post-TB cavity) or is it a discrete, possibly spiculated mass (favoring carcinoma)?",
      "option_labels": ["B", "E"],
      "image_ids": ["image:1"]
    }
  ],
  "missing_attributes": ["cavity wall thickness", "air-fluid level", "spiculation/margins", "calcification", "hilar lymphadenopathy", "contrast enhancement (not available on plain X-ray)"],
  "recommended_view": "compare",
  "uncertain": true
}
